<?phpif (!defined('BASEPATH')) {    exit('No direct script access allowed');}include_once APPPATH . '/modules/layout/controllers/Layout.php';class Customer_types extends Layout {    private $_module_slug = 'loai-khach-hang';    private $_module_name = 'loại khách hàng';    function __construct() {        parent::__construct();        $this->load->model('customer_types/m_customer_types', 'M_customer_types');        $this->_data['breadcrumbs_module_name'] = ucfirst($this->_module_name);        $this->_data['breadcrumbs_module_func'] = 'Danh sách';        $this->_data['module_slug'] = $this->_module_slug;        $this->_data['module_name'] = $this->_module_name;    }    function default_args() {        $order_by = array(            'order' => 'ASC',            'edit_time' => 'DESC',            'name' => 'ASC'        );        $args = array();        $args['order_by'] = $order_by;        return $args;    }    function counts($args) {        return $this->M_customer_types->counts($args);    }    function get($id) {        return $this->M_customer_types->get($id);    }    function get_max_order() {        $args = $this->default_args();        $order_by = array(            'order' => 'DESC'        );        $args['order_by'] = $order_by;        $perpage = 1;        $offset = 0;        $rows = $this->M_customer_types->gets($args, $perpage, $offset);        $max_order = isset($rows[0]['order']) ? $rows[0]['order'] : 0;        return (int) $max_order;    }    function gets($in_id = array()) {        $this->load->model('m_customer_types', 'M_customer_types');        $args = $this->default_args();        if (is_array($in_id) && !empty($in_id)) {            $args = array();            $args['in_id'] = $in_id;        }        return $this->M_customer_types->gets($args);    }    function gets_in_id() {        $this->load->model('m_customer_types', 'M_customer_types');        $args = $this->default_args();        return $this->M_customer_types->gets($args);    }    function admin_index() {        $this->redirect_admin();        $this->load->library('form_validation');        $this->_plugins_css_admin[] = array(            'folder' => 'bootstrap3-dialog/css',            'name' => 'bootstrap-dialog'        );        $this->_plugins_script_admin[] = array(            'folder' => 'bootstrap3-dialog/js',            'name' => 'bootstrap-dialog'        );        $this->set_plugins_admin();        $this->_modules_script[] = array(            'folder' => 'customer_types',            'name' => 'admin-items'        );        $this->set_modules();        $get = $this->input->get();        $this->_data['get'] = $get;        $args = $this->default_args();        if (isset($get['q']) && trim($get['q']) != '') {            $args['name'] = $get['q'];        }        $total = $this->counts($args);        $perpage = isset($get['per_page']) ? $get['per_page'] : $this->config->item('per_page');        $segment = 4;        $this->load->library('pagination');        $config['total_rows'] = $total;        $config['per_page'] = $perpage;        $config['full_tag_open'] = '<ul class="pagination no-margin pull-right">';        $config['full_tag_close'] = '</ul><!--pagination-->';        $config['first_link'] = '&laquo;';        $config['first_tag_open'] = '<li class="prev page">';        $config['first_tag_close'] = '</li>';        $config['last_link'] = '&raquo;';        $config['last_tag_open'] = '<li class="next page">';        $config['last_tag_close'] = '</li>';        $config['next_link'] = 'Trang trước &rarr;';        $config['next_tag_open'] = '<li class="next page">';        $config['next_tag_close'] = '</li>';        $config['prev_link'] = '&larr; Trang sau';        $config['prev_tag_open'] = '<li class="prev page">';        $config['prev_tag_close'] = '</li>';        $config['cur_tag_open'] = '<li class="active"><a href="">';        $config['cur_tag_close'] = '</a></li>';        $config['num_tag_open'] = '<li class="page">';        $config['num_tag_close'] = '</li>';        if (!empty($get)) {            $config['base_url'] = base_url($this->_module_slug);            $config['suffix'] = '?' . http_build_query($get, '', "&");            $config['first_url'] = base_url($this->_module_slug . '?' . http_build_query($get, '', "&"));            $config['uri_segment'] = $segment;        } else {            $config['base_url'] = base_url($this->_module_slug);            $config['uri_segment'] = $segment;        }        $this->pagination->initialize($config);        $pagination = $this->pagination->create_links();        $offset = ($this->uri->segment($segment) == '') ? 0 : $this->uri->segment($segment);        $rows = $this->M_customer_types->gets($args, $perpage, $offset);        $this->_data['rows'] = $rows;        $this->_data['pagination'] = $pagination;        $this->_data['title'] = 'Danh sách ' . $this->_module_name . ' - ' . $this->_data['title'];        $this->_data['main_content'] = 'admin/view_page_index';        $this->load->view('layout/admin/view_layout', $this->_data);    }    function admin_add() {        $data = array(            'name' => $this->input->post('name'),            'add_time' => time(),            'edit_time' => 0,            'order' => $this->get_max_order() + 1,            'status' => 1        );        return $this->M_customer_types->add($data);    }    function admin_update($id) {        $data = array(            'name' => $this->input->post('name'),            'edit_time' => time(),        );        return $this->M_customer_types->update($id, $data);    }    function re_order() {        $rows = $this->gets();        if (is_array($rows) && !empty($rows)) {            $i = 0;            foreach ($rows as $value) {                $i++;                $data = array(                    'order' => $i                );                $this->M_customer_types->update($value['id'], $data);            }        }    }    function admin_delete() {        $this->load->module('users');        $this->_message_success = 'Đã xóa ' . $this->_module_name . '!';        $this->_message_warning = ucfirst($this->_module_name) . ' này không tồn tại!';        if ($this->users->validate_admin_logged_in() == TRUE) {            $row = $this->get($id);            if ($id != 0 && !empty($row)) {                if (modules::run('price/validate_exist_unit', $id)) {                    $notify_type = 'danger';                    $notify_content = ucfirst($this->_module_name) . ' này đang sử dụng nên không xóa được!';                } else {                    if ($this->M_customer_types->delete($id)) {                        add_activities(array(                            'action' => NULL,                            'activity' => "Người dùng xóa " . $this->_module_name . " #ID: $id",                            'data' => serialize(array('old' => $row, 'new' => NULL)),                        ));                        $this->re_order();                        $notify_type = 'success';                        $notify_content = $this->_message_success;                    } else {                        $notify_type = 'danger';                        $notify_content = $this->_message_danger;                    }                }            } else {                $notify_type = 'warning';                $notify_content = $this->_message_warning;            }            $this->set_notify_admin($notify_type, $notify_content);            redirect(base_url($this->_module_slug));        } else {            $notify_type = 'danger';            $notify_content = $this->_message_banned;            $this->set_notify_admin($notify_type, $notify_content);            redirect(base_url($this->_module_slug));        }    }    function admin_main() {        $this->redirect_admin();        $post = $this->input->post();        if (!empty($post)) {            $action = $this->input->post('action');            if ($action == 'update') {                $this->_message_success = 'Đã cập nhật ' . $this->_module_name . '!';                $this->_message_warning = 'Không có ' . $this->_module_name . ' nào để cập nhật!';                $ids = $this->input->post('ids');                $orders = $this->input->post('order');                $count = count($orders);                if (!empty($ids) && !empty($orders)) {                    for ($i = 0; $i < $count; $i++) {                        $data = array(                            'order' => $orders[$i]                        );                        $id = $ids[$i];                        if ($this->M_customer_types->update($id, $data)) {                            $notify_type = 'success';                            $notify_content = $this->_message_success;                        } else {                            $notify_type = 'danger';                            $notify_content = $this->_message_danger;                        }                    }                } else {                    $notify_type = 'warning';                    $notify_content = $this->_message_warning;                }                $this->set_notify_admin($notify_type, $notify_content);                redirect(base_url($this->_module_slug));            } elseif ($action == 'delete') {                $this->_message_success = 'Đã xóa các ' . $this->_module_name . ' được chọn!';                $this->_message_warning = 'Bạn chưa chọn ' . $this->_module_name . ' nào!';                $ids = $this->input->post('idcheck');                if (is_array($ids) && !empty($ids)) {                    foreach ($ids as $id) {                        if ($this->M_customer_types->delete($id)) {                            $notify_type = 'success';                            $notify_content = $this->_message_success;                        } else {                            $notify_type = 'danger';                            $notify_content = $this->_message_danger;                        }                    }                    add_activity("Người dùng xóa các " . $this->_module_name . " #ID: " . implode(', ', $ids));                    $this->re_order();                } else {                    $notify_type = 'warning';                    $notify_content = $this->_message_warning;                }                $this->set_notify_admin($notify_type, $notify_content);                redirect(base_url($this->_module_slug));            } elseif ($action == 'content') {                redirect(base_url($this->_module_slug . '/them'));            }        } else {            redirect(base_url($this->_module_slug));        }    }    function admin_content() {        $this->redirect_admin();        $this->_plugins_script_admin[] = array(            'folder' => 'jquery-validation',            'name' => 'jquery.validate'        );        $this->_plugins_script_admin[] = array(            'folder' => 'jquery-validation/localization',            'name' => 'messages_vi'        );        $this->set_plugins_admin();        $this->_modules_script[] = array(            'folder' => 'customer_types',            'name' => 'admin-validate-content'        );        $this->set_modules();        $post = $this->input->post();        if (!empty($post)) {            $this->load->helper('language');            $this->lang->load('form_validation', 'vietnamese');            $this->form_validation->set_error_delimiters('<span class="help-block">', '</span>');            $this->form_validation->set_rules('name', 'Tên ' . $this->_module_name, 'trim|required');            if ($this->form_validation->run($this)) {                if ($this->input->post('id')) {                    $err = FALSE;                    $id = $this->input->post('id');                    $row_old = $this->get($id);                    if (!$this->admin_update($id)) {                        $err = TRUE;                    }                    if ($err === FALSE) {                        $row_new = $this->get($id);                        add_activities(array(                            'action' => NULL,                            'activity' => "Người dùng cập nhật " . $this->_module_name . " #ID: $id",                            'data' => serialize(array('old' => $row_old, 'new' => $row_new)),                        ));                        $notify_type = 'success';                        $notify_content = 'Cập nhật ' . $this->_module_name . ' thành công!';                        $this->set_notify_admin($notify_type, $notify_content);                        redirect(base_url($this->_module_slug));                    } else {                        $notify_type = 'danger';                        $notify_content = 'Có lỗi xảy ra!';                        $this->set_notify_admin($notify_type, $notify_content);                    }                } else {                    $err = FALSE;                    $insert_id = $this->admin_add();                    if ($insert_id == 0) {                        $err = TRUE;                    }                    if ($err === FALSE) {                        $row_new = $this->get($insert_id);                        add_activities(array(                            'action' => NULL,                            'activity' => "Người dùng thêm " . $this->_module_name . " #ID: $insert_id",                            'data' => serialize(array('old' => NULL, 'new' => $row_new)),                        ));                        $notify_type = 'success';                        $notify_content = ucfirst($this->_module_name) . ' đã được thêm!';                        $this->set_notify_admin($notify_type, $notify_content);                        redirect(base_url($this->_module_slug));                    } else {                        $notify_type = 'danger';                        $notify_content = 'Có lỗi xảy ra!';                        $this->set_notify_admin($notify_type, $notify_content);                    }                }            }        }        $title = 'Thêm ' . $this->_module_name . ' - ' . $this->_data['breadcrumbs_module_name'] . ' - ' . $this->_data['title'];        $id = ($this->uri->segment(3) == '') ? 0 : $this->uri->segment(3);        if ($id != 0) {            $row = $this->get($id);            $this->_data['row'] = $row;            $title = 'Cập nhật ' . $this->_module_name . ' - ' . $this->_data['breadcrumbs_module_name'] . ' - ' . $this->_data['title'];        }        $this->_data['title'] = $title;        $this->_data['main_content'] = 'admin/view_page_content';        $this->load->view('layout/admin/view_layout', $this->_data);    }}/* End of file customer_typess.php *//* Location: ./application/modules/controllers/customer_typess.php */